  function paint(){const b=campaign.battle,canvas=$('field');if(b&&canvas&&view==='run')spectator.draw(canvas,b,$('moment-banner'));}
  function archive(){screen();view='archive';setContent(`<div class="section-head"><h1>발견 기록</h1>${btn('캐릭터로','home')}</div>${window.Discovery?.panel(campaign.meta,true)||''}<p class="note">영구 소유 카드가 아닌 발견 기록입니다. 원정 보상 카드는 새 원정에서 다시 획득해야 합니다.</p><div class="card-area">${K.playableCharacters().flatMap(c=>c.reward).map(key=>`<section class="kit-card">${window.CardVisuals.identity(key)}<p>${campaign.meta.discovered.includes(key)?esc(D.cards[key].desc):'아직 발견하지 않았습니다.'}</p><small>${campaign.meta.discovered.includes(key)?'발견 기록 · 원정마다 다시 획득':'미발견'}</small></section>`).join('')}</div>`);}
  function report(){screen();view='report';const r=campaign.meta.history[0];if(!r){home();return;}setContent(`<div class="section-head"><div><h1>${r.success?'원정 완주':'원정 귀환'}</h1><p>${esc(r.reason)} · ${r.time.toFixed(1)}초</p></div>${btn('캐릭터로','home')}</div>${r.challenge?`<section class="panel challenge-result"><h2>공개 도전 · ${esc(C.challenges[r.challenge.id].name)}</h2><p>고정 시드 ${r.challenge.seed} · 레벨 5 · ${r.success?'완주 기록 저장':'귀환 기록 저장'} · 영구 경험치 없음</p><p>목표: ${esc(C.challenges[r.challenge.id].goal)} · ${r.goalMet?'달성':'미달성'}</p></section>`:''}${r.success?'':window.ExpeditionFlow.nextPanel(r)}${window.Discovery?.reportPanel(r)||''}${r.success?window.ExpeditionFlow.nextPanel(r):''}${window.ExpeditionReview.panel(r)}${window.ExpeditionReview.growthPanel(r)}<section class="hero"><h2>이번 원정의 조합을 마쳤습니다</h2><p>보상 카드 ${r.cards.length}장과 진화 ${r.evolved}장이 초기화됐습니다. 캐릭터·기초 카드·레벨·발견 기록은 남았습니다.</p><div class="row">${btn('기초 덱으로 다시 출발','start','',true)}</div></section><details class="panel"><summary>원정 출발·최종 덱과 선택 기록</summary><p><strong>출발</strong> · ${r.initialDeck?window.BattleInsights.deckText({pool:r.initialDeck,deck:r.initialDeck.map(c=>c.id)}):'이전 저장 · 미기록'}</p><p><strong>최종</strong> · ${r.finalDeck?window.BattleInsights.deckText({pool:r.finalDeck,deck:r.finalDeck.map(c=>c.id)}):'이전 저장 · 미기록'}</p><h3>선택한 경로와 대가</h3>${(r.routeChoices||[]).map(x=>`<p>${x.depth+1}. ${esc(x.name)} · ${esc(x.cost||'갈림길 없음')}</p>`).join('')}<ol>${r.journal.map(text=>`<li>${esc(text)}</li>`).join('')}</ol></details><div class="report-list panel">${r.results.map((b,i)=>`<div>${esc(b.name)} · ${b.time.toFixed(1)}초 · 남은 HP ${Math.round(b.hp.reduce((n,h)=>n+h,0))}</div>${window.ResultStory.panel(b,window.ResultStory.baseline(r,i),'report',i)}<details class="panel result-details"><summary>전체 전투 통계·운영 기록</summary>${window.BattleAwareness.recap(b)}${autoRecap(b)}${traitReport(b)}${window.BattleInsights.panel(b)}</details>`).join('')}</div>`);}
  function deploymentPanel(q){
    const x=q.deploymentComparison;if(!x)return '';const a=x.before,b=x.after,names=new Map(a.actors.map(r=>[r.id,r.name])),seconds=n=>n==null?'없음':n.toFixed(2)+'초',num=n=>n.toFixed(1),ko=r=>r.firstKO?esc(names.get(r.firstKO.actor))+' · '+seconds(r.firstKO.at):'없음',targets=r=>r.firstTargets.map(t=>esc(names.get(t.actor))+' → '+esc(names.get(t.target))).join('<br>')||'없음';
    const rows=[['승패',a.winner===0?'승리':'패배',b.winner===0?'승리':'패배'],['교전 시간',seconds(a.time),seconds(b.time)],['남은 HP / 생존',num(a.hp)+' / '+a.survivors+'명',num(b.hp)+' / '+b.survivors+'명'],['적 첫 기본 표적',targets(a),targets(b)],['아군 첫 기본 공격',seconds(a.firstAttack[0]),seconds(b.firstAttack[0])],['적 첫 기본 공격',seconds(a.firstAttack[1]),seconds(b.firstAttack[1])],['방패병 분담 피해',num(a.protected),num(b.protected)],['카드 엄호 분담',num(a.covered),num(b.covered)],['적 광역 최대 동시 피해',a.areaMax[1]+'명',b.areaMax[1]+'명'],['적 광역 다수 피해 횟수',a.areaMulti[1]+'회',b.areaMulti[1]+'회'],['위험 구역 최대 동시 피해',a.zoneMax[1]+'명',b.zoneMax[1]+'명'],['위험 구역 다수 피해 횟수',a.zoneMulti[1]+'회',b.zoneMulti[1]+'회'],['첫 아군 전투불능',ko(a),ko(b)],['주변 회복 / 직선 피해',num(a.circleHeal)+' / '+num(a.lineDamage),num(b.circleHeal)+' / '+num(b.lineDamage)]];
    const table=list=>`<div class="deployment-table"><table><thead><tr><th>관측 항목</th><th>원본 배치</th><th>변경 배치</th></tr></thead><tbody>${list.map(([name,left,right])=>`<tr><th>${name}</th><td>${left}</td><td class="${left!==right?'deployment-change':''}">${right}</td></tr>`).join('')}</tbody></table></div>`;const mainRows=[rows[0],rows[1],rows[2],rows[12]];
    const label=r=>r.formation.map((slot,i)=>esc(K.characters[i].name)+' '+window.Formation.label(slot,r.formationVersion)).join(' / ');
    return `<section class="panel deployment-comparison"><h2>배치만 비교 · ${x.same?'같은 배치 재현':'원본과 변경 배치'}</h2><p class="note">당시 덱·체력·태세·오토 방침 고정. 위치만 변경합니다.</p>${JSON.stringify(q.formation)!==JSON.stringify(b.formation)?'<p class="warning">배치가 다시 변경되었습니다. 다시 비교하면 새 위치를 반영합니다.</p>':''}${table(mainRows)}<details data-inline><summary>표적·보호·범위 피해 비교</summary>${table(rows.filter(r=>!mainRows.includes(r)))}</details><details data-inline><summary>사용한 배치·측정 기준</summary><p>당시 덱·진화·체력·레벨·태세·적·시드·방침을 양쪽에 동일하게 적용합니다. 연습 덱 수정은 이 비교에 적용하지 않습니다.</p><p>원본: ${label(a)}</p><p>변경: ${label(b)}</p><p>첫 표적은 적이 처음 결정한 기본 공격 대상입니다. 첫 기본 공격은 실제 실행 시점이며 카드 피해와 구분합니다. 광역은 체력 피해가 발생한 직접 대상을 세며, 차단·보호막 흡수·보호자 분담은 동시 피격 수에 넣지 않습니다.</p><p>원본 수동 교전도 양쪽 모두 오토로 새로 계산합니다. 같은 시드와 초기 손패지만 배치로 행동이 달라지면 이후 난수 소비도 달라질 수 있습니다. 한 번의 비교는 모든 적에 대한 우위를 보장하지 않습니다.</p></details></section>`;
  }
  function practiceView(){
    screen();view='practice';const q=practiceSession;if(!q){report();return;}const busy=!q.editable(),V=window.CardVisuals,original=q.reference;if(q.battle&&!q.battle.s.ended){screen(true);document.body.classList.add('practice-battle-mode');}
    setContent(`<div class="section-head"><div><h1>${esc(original.name)} · 연습</h1><p>시작 체력·레벨·태세·적·시드 고정 · 보상과 경험치 없음</p></div>${btn(practiceOrigin==='home'?'거점으로':'원정 결과로','practice-back')}</div>${q.contentTrial?`<section class="panel"><h2>${esc(q.contentTrial.name)} · 체험 목표</h2><p class="note">레벨 ${q.record.config.levels[0]} · 시드 ${q.record.config.seed} · 만전 체력 출발 · 같은 조건 유지</p><p>${esc(q.contentTrial.intent)}</p><p>${q.contentTrial.responses.map(esc).join(' / ')}</p><p class="note">${esc(q.contentTrial.cost)}</p><p class="note">아래 기준은 기초 추격 덱·공격 방침·추천 배치의 자동전투입니다. 기존 원정에는 추가되지 않습니다.</p></section>`:''}<section class="panel"><strong>${q.contentTrial?'기준 자동전투':'원본 교전'} · ${window.BattleInsights.summary(original)}</strong><p class="note">${original.practice.config.control==='manual'||original.stats.interventions>0?'원본은 수동 조작이 포함된 교전입니다. 연습은 오토로 진행하므로 원본 행동을 재현하지 않습니다.':'같은 덱·방침·배치는 같은 시작 조건으로 재실행합니다.'} 덱 변경 뒤 난수 소비가 달라질 수 있으므로 한 번의 비교가 모든 상황의 우위를 보장하지 않습니다.</p>${original.practice.config.tactic?'<p class="warning">원정 규칙 고정: 추격 릴레이 · 활성 중 추격 공격 명령 +1초</p>':''}<details class="practice-recipes" data-inline ${q.deckOrigin==='preset'?'open':''}><summary>기초 덱으로 비교 · 호위 / 추격 / 공명</summary><p class="note">미진화 기초 카드 20장으로 바꿉니다. 체력·레벨·태세·적·시드는 유지하고, 현재 배치·방침도 유지합니다. 원정 덱과 보상은 바뀌지 않습니다.</p><div class="row">${K.startingDecks.map(p=>btn(p.name+'으로 비교 준비','practice-preset',`data-id="${p.id}" ${busy?'disabled':''}`)).join('')}</div>${q.deckOrigin==='preset'?`<p class="note">현재 비교 덱 · ${esc(K.startingDecks.find(p=>p.id===q.presetId)?.name||'기초 덱')}</p>`:''}</details><label><input id="practice-basics" type="checkbox" ${q.basics?'checked':''} ${busy?'disabled':''}> 실험: 전체 기초 키트 사용</label><p class="note">기본은 당시 보유한 카드만 사용합니다. 기초 키트 실험은 편성을 원본으로 되돌리고 알려진 기초 카드를 추가합니다. 보상 카드는 새로 지급하지 않습니다.</p><label>오토 방침 <select id="practice-policy" ${busy?'disabled':''}>${['attack','protect',...(q.policy==='balanced'?['balanced']:[])].map(k=>`<option value="${k}" ${q.policy===k?'selected':''}>${{attack:'공격 중심',protect:'보호 중심',balanced:'기존 운영'}[k]}</option>`).join('')}</select></label>${formationPanel(true)}<div class="row">${btn('배치만 비교 · 당시 덱 고정','practice-compare',busy||!q.record.config.formation?'disabled':'')}</div><p>편성 ${q.ids.length} / 20장</p>${traitPanel(q.ids.map(id=>q.pool.find(c=>c.id===id)))}<div class="row">${btn('이 덱으로 연습 시작','practice-start',busy||D.validateDeck(q.ids,q.pool)?'disabled':'',true)}${btn('이번 교전 덱으로','practice-reset',busy?'disabled':'')}${btn('변경 전 덱 재현','practice-previous',busy||!q.canHistorical(q.previousDeck)?'disabled':'')}${btn('출발 덱으로 재현','practice-starting',busy||!q.canHistorical(q.startingDeck)?'disabled':'')}<p class="note">과거 기록의 카드·진화 상태를 연습에서만 재현합니다. 원정에 카드가 지급되지 않습니다. 출발 덱 재현은 초기 카드·미진화 상태와 당시 배치·방침을 적용하고, 이 교전의 시작 HP·레벨·적은 유지합니다.</p></div><p class="warning">${esc(D.validateDeck(q.ids,q.pool))}</p></section><section class="panel practice-stage"><div class="battle-watch"><strong id="practice-status"></strong><label>관전 속도 <select id="practice-speed">${[1,1.5,2].map(n=>`<option value="${n}" ${(q.speed||campaign.meta.settings.speed)===n?'selected':''}>${n}배</option>`).join('')}</select></label>${btn('관전 일시정지','practice-pause',!busy?'disabled':'')}</div><canvas id="practice-field" width="960" height="390" aria-label="연습 전투"></canvas><div id="practice-moment" class="moment-banner"></div><p id="practice-decision" class="note"></p></section><details id="practice-deck-details" class="panel" ${q.battle?'':'open'}><summary>연습 덱 수정 · ${q.pool.length-q.ids.length}장 미편성</summary><div class="practice-pool">${q.pool.map(c=>`<article class="visual-card ${q.ids.includes(c.id)?'practice-equipped':''}" style="--card-trait:${V.color(c.key)}">${V.body(c,{party:practiceSession?.record.config.party||campaign.run?.party})}${btn(q.ids.includes(c.id)?'편성에서 빼기':'편성에 넣기','practice-copy',`data-id="${c.id}" ${busy?'disabled':''}`)}</article>`).join('')}</div></details>${deploymentPanel(q)}<div id="practice-results">${q.results.map((r,i)=>`<section class="panel"><h3>연습 ${q.results.length-i} · ${r.presetId?(K.startingDecks.find(p=>p.id===r.presetId)?.name||'기초 덱 비교'):r.startingDeck?'출발 덱 재현':r.historicalDeck?'과거 덱 재현':r.expandedBasics?'기초 키트 실험':'당시 보유 카드'} · ${r.autoPolicy==='protect'?'보호':r.autoPolicy==='balanced'?'기존 운영':'공격'} 중심</h3><p>${window.BattleInsights.summary(r)}</p><p class="note">배치 · ${JSON.stringify(r.practice?.config.formation||null)===JSON.stringify(original.practice.config.formation||null)?'원본 유지':'변경'}${r.practice?.config.formation?' · '+r.practice.config.formation.map((slot,role)=>esc(slotCharacter(role,r.practice.config).name)+' '+window.Formation.label(slot,r.practice.config.formationVersion??1)).join(' / '):' · 이전 교전 위치'}</p><p class="note">원본 대비 시간 ${(r.time-original.time).toFixed(1)}초 · 남은 HP ${(r.hp.reduce((n,h)=>n+h,0)-original.hp.reduce((n,h)=>n+h,0)).toFixed(1)} · 승패와 카드 기여도를 함께 비교하세요.</p>${window.BattleInsights.panel(r)}</section>`).join('')}</div>`);
    practiceUpdate();
  }
  function practiceUpdate(){const b=practiceSession?.battle;if(!$('practice-field'))return;const pause=document.querySelector('[data-action=practice-pause]');pause.textContent=b?.s.paused&&!b.s.ended?'관전 재개':'관전 일시정지';pause.setAttribute('aria-pressed',String(!!b?.s.paused&&!b.s.ended));if(!b){$('practice-status').textContent='덱을 확인하고 연습을 시작하세요.';return;}const s=b.s;$('practice-status').textContent=s.ended?(s.winner===0?'연습 승리':'연습 패배'):s.paused?'일시정지':s.t.toFixed(1)+' / 180초 · 관전 중';$('practice-decision').textContent=s.autoLast?.reason||b.autoTraitStatus();spectator.draw($('practice-field'),b,$('practice-moment'));}
  function practiceStep(dt){if(!practiceSession)return;const wasReported=practiceSession.reported;practiceSession.step(dt);if(!wasReported&&practiceSession.reported)practiceView();else practiceUpdate();}
  function settings(){screen();view='settings';setContent(`<div class="section-head"><h1>설정·저장</h1>${btn('캐릭터로','home')}</div><section class="panel character-settings"><details class="effect-rules" data-inline><summary>실험용 수동 기본 설정</summary><div class="setting"><div><h3>전투 운영</h3><small>언제든 수동·오토를 바꿀 수 있습니다.</small></div><select id="control"><option value="auto" ${campaign.meta.settings.control==='auto'?'selected':''}>오토</option><option value="manual" ${campaign.meta.settings.control==='manual'?'selected':''}>수동</option></select></div></details>${policySelect()}<div class="setting"><div><h3>스킬 연출</h3><small>타격·보호 정보는 모든 설정에서 표시됩니다.</small></div><select id="presentation-mode" aria-label="스킬 연출"><option value="full" ${spectator.director.mode==='full'?'selected':''}>전체</option><option value="simple" ${spectator.director.mode==='simple'?'selected':''}>간소</option><option value="off" ${spectator.director.mode==='off'?'selected':''}>장식 연출 끔 · 판정 정보 유지</option></select></div><div class="setting"><div><h3>대사·초상화 반복</h3><small>현재 브라우저에서 원정과 체험에 공통 적용합니다.</small></div><select id="presentation-frequency" aria-label="대사·초상화 반복"><option value="all" ${spectator.director.frequency==='all'?'selected':''}>매번</option><option value="highlights" ${spectator.director.frequency==='highlights'?'selected':''}>주요 장면</option><option value="once" ${spectator.director.frequency==='once'?'selected':''}>전투당 첫 사용</option></select></div><div class="setting"><div><h3>효과음 음량</h3><small>소리는 전투에서 직접 켭니다. 0%는 무음입니다.</small></div><label><input type="range" id="presentation-volume" aria-label="효과음 음량" min="0" max="100" step="5" value="${Math.round(spectator.volume*100)}"><output id="presentation-volume-value">${Math.round(spectator.volume*100)}%</output></label></div><div class="setting"><h3>전투 속도</h3><select id="speed">${[1,1.5,2].map(n=>`<option value="${n}" ${campaign.meta.settings.speed===n?'selected':''}>${n}배</option>`).join('')}</select></div><div class="setting"><div><h3>원정 저장</h3><small>이어하기는 보상·진화·현재 전투를 유지합니다. 원정 종료와는 다릅니다.</small></div><div class="row">${btn('저장 다운로드','export')}${btn('저장 불러오기','import')}</div></div><details class="effect-rules"><summary>전투 효과 규칙</summary><p class="note">피해는 방어 감소 → 보호막 → 피해 분담 → 체력 감소 → 반격 순서로 처리합니다. 엄호가 있으면 방패병 보호보다 먼저 적용하며, 보호자는 한 명만 피해를 나눠 받습니다.</p><p class="note">같은 보호막·방어·공격 강화는 합산하지 않고 강한 수치와 긴 남은 시간을 유지합니다. 차단·반격은 한 번만 보유하며, 도발은 마지막 시전자로 바뀝니다.</p><p class="note">기술의 시전자가 쓰러지거나 유효한 대상이 없어지면 남은 타격·접근과 행동 잠금을 정리합니다. 사용한 카드와 명령 회복시간은 유지합니다. 검무가 차단되면 남은 타격도 중단됩니다.</p><p class="note">보호막이 모두 막으면 엄호 피해와 엄호 반격은 발생하지 않습니다. 자신의 보호막으로 받은 공격은 받아칠 수 있습니다.</p></details><p class="note">기존 게임의 저장은 별도로 보관되어 있습니다. <a href="index.html?v=auto">이전 원정 이어가기</a></p>${loadError?`<p class="warning">${esc(loadError)}</p>${btn('읽지 못한 원본 다운로드','raw-export')+btn('원본 보관 후 새로 시작','recover')}`:''}</section>`);}
  function advance(dt,refresh=true){const b=campaign.battle;if(!b)return;b.step(dt);if(campaign.observe()){save();render();}else if(refresh)update();}
